const STY = (bg) => `position:absolute;left:70px;width:800px;height:160px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.4);background:${bg};color:#ffffff;font-size:44px;font-weight:800;line-height:1.1;opacity:0;`;
const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <div id="stars" style="position:absolute;top:130px;width:100%;text-align:center;color:#ffffff;font-size:95px;font-weight:900;letter-spacing:-3px;opacity:0;">0 STARS</div>
  <div id="c0" style="${STY(B1)}top:310px;">MESSY AI CHAT</div>
  <div id="c1" style="${STY(B2)}top:540px;">SPEC-KIT TOOLKIT</div>
  <div id="c2" style="${STY(B1)}top:770px;">ENGINEERING STANDARDS</div>
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:10;stroke-linecap:round;opacity:0.2">
    <path id="l0" d="M470 470 L470 540" />
    <path id="l1" d="M470 700 L470 770" />
  </svg>
`;

const starEl = root.querySelector('#stars');
const cards = [0, 1, 2].map(i => root.querySelector(`#c${i}`));
const lines = [0, 1].map(i => {
  const el = root.querySelector(`#l${i}`);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  // Heading: Number builds up
  const s0 = spr(tf, 0, 0.8, 4);
  starEl.style.opacity = clamp(s0 * 2);
  starEl.style.transform = `translateY(${lerp(30, 0, E_OUT(clamp(s0)))}px) scale(${lerp(0.9, 1, E_OUT(clamp(s0)))})`;
  const countP = clamp(tf / 2.2);
  const currentStars = Math.floor(lerp(0, 147523, E_OUT(countP)));
  starEl.textContent = currentStars.toLocaleString('en-US') + ' STARS';

  // Cards: Sequential entrance
  cards.forEach((el, i) => {
    const s = spr(tf, 0.6 + i * 0.7, 0.85, 8);
    el.style.opacity = clamp(s * 2);
    const yMove = lerp(40, 0, E_OUT(clamp(s)));
    const scale = lerp(0.95, 1, E_OUT(clamp(s)));
    el.style.transform = `translateY(${yMove}px) scale(${scale})`;
  });

  // Connectors: Drawn between cards
  lines.forEach((line, i) => {
    const s = spr(tf, 1.1 + i * 0.7, 0.9, 6);
    line.el.style.strokeDashoffset = line.len * (1 - clamp(s));
    line.el.style.opacity = clamp(s * 1.5) * 0.3;
  });
}
